1	#pragma once
2	
3	#include "hybrid/abstract_command.hpp"
4	#include "hybrid/dmi_poll.hpp"
5	#include "hybrid/program_buffer.hpp"
6	#include "hybrid/state_abi.h"
7	#include "hybrid/v_regfile_xfer.hpp"
8	
9	#include <array>
10	#include <cstdint>
11	#include <stdexcept>
12	
13	namespace hybrid {
14	
15	struct DmiBus
16	{
17	  virtual ~DmiBus() = default;
18	  virtual void write(uint8_t reg, uint32_t value) = 0;
19	  virtual auto read(uint8_t reg) -> uint32_t = 0;
20	};
21	
22	class ResumeDriver
23	{
24	public:
25	  static constexpr uint8_t kData0      = 0x04;
26	  static constexpr uint8_t kData1      = 0x05;
27	  static constexpr uint8_t kDmcontrol  = 0x10;
28	  static constexpr uint8_t kDmstatus   = 0x11;
29	  static constexpr uint8_t kAbstractcs = 0x16;
30	  static constexpr uint8_t kCommand    = 0x17;
31	
32	  static constexpr uint16_t kCsrDpc      = 0x7B1;
33	  static constexpr uint16_t kCsrMstatus  = 0x300;
34	  static constexpr uint16_t kCsrMtvec    = 0x305;
35	  static constexpr uint16_t kCsrMcycle   = 0xB00;
36	  static constexpr uint16_t kCsrMinstret = 0xB02;
37	  static constexpr uint16_t kCsrVstart   = 0x008;
38	  static constexpr uint16_t kCsrVxsat    = 0x009;
39	  static constexpr uint16_t kCsrVxrm     = 0x00A;
40	  static constexpr uint16_t kCsrVcsr     = 0x00F;
41	  static constexpr uint16_t kCsrVtype    = 0xC21;
42	  static constexpr uint16_t kCsrVl       = 0xC20;
43	
44	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
45	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
46	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
47	
48	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
49	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
50	
51	  static constexpr uint32_t kAbstractcsBusy        = 1u << 12;
52	  static constexpr uint32_t kAbstractcsCmderrMask  = 0x7u << 8;
53	
54	  static constexpr unsigned kPollIterations = kDmiPollIterations;
55	
56	  explicit ResumeDriver(DmiBus& bus)
57	      : bus_{bus}
58	  {}
59	
60	  void resume(const hybrid_state_v1& state)
61	  {
62	    if (state.magic != HYBRID_STATE_MAGIC)
63	      throw std::runtime_error("ResumeDriver::resume: bad magic");
64	    if (state.version != HYBRID_STATE_VERSION)
65	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
66	
67	    // dmactive must transition 0->1 in its own write before any other
68	    // DMCONTROL bit is honored (RISC-V Debug Spec).
69	    bus_.write(kDmcontrol, kDmcontrolDmactive);
70	    request_halt();
71	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
72	
73	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
74	    // accepted (FS or VS == Off disables the extension and the hart NACKs
75	    // the writes). The drained state.mstatus may legitimately carry FS or
76	    // VS at Off (e.g. an OS context-switched the regs away before the
77	    // trigger fired) -- gating the write on the drained field skips the
78	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
79	    // write mstatus when either extension is in scope; force-OR Initial
80	    // when the drained field is Off. QEMU2 receives the unmodified drained
81	    // state.mstatus via the gdbstub passthrough, so this enable is local
82	    // to the vsim phase only.
83	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
84	      uint64_t enable_mstatus = state.mstatus;
85	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & 0x6000ULL) == 0)
86	        enable_mstatus |= 0x2000ULL;   // FS = Initial
87	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & 0x600ULL)  == 0)
88	        enable_mstatus |= 0x200ULL;    // VS = Initial
89	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
90	    }
91	
92	    // FPR restore (requires mstatus.FS enabled above).
93	    if (state.flags & HYBRID_FLAG_FP) {
94	      for (uint16_t i = 0; i < 32; ++i)
95	        write_64bit_register(regno_fpr(i), state.fpr[i]);
96	    }
97	
98	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
99	    // the GPR loop overwrites x5 afterward so state is preserved).
100	    if (state.flags & HYBRID_FLAG_V) {
101	      // V data regfile: reload v0..v31 from the shared scratch region via the
102	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
103	      // because the sweep's own vsetvl (e8/m1) clobbers vtype/vl/vstart, which
104	      // the restore then overwrites with the architectural values. The sweep
105	      // uses x5/x6/x7 as scratch (x7 is the base pointer); the GPR loop below
106	      // restores all three. The wire format reserves HYBRID_VLEN_BYTES_MAX per
107	      // register, so that -- not the runtime vlenb -- is the scratch stride.
108	      pb_v_data_sweep(bus_, kVScratchGpa, HYBRID_VLEN_BYTES_MAX, state.vlenb,
109	                      /*load=*/true);
110	
111	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
112	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
113	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
114	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
115	      write_64bit_register(regno_gpr(5), state.vl);
116	      write_64bit_register(regno_gpr(6), state.vtype);
117	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
118	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
119	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
120	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
121	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
122	      write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
123	      write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
124	    }
125	
126	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite).
127	    for (uint16_t i = 1; i < 32; ++i)
128	      write_64bit_register(regno_gpr(i), state.gpr[i]);
129	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
130	
131	    write_csr_tolerant(kCsrMtvec, state.mtvec);
132	
133	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
134	    // from QEMU1's drain value. Without this, vsim's local counter starts
135	    // at zero and any cycles spent inside the ROI vanish at the QEMU2
136	    // boundary. PB fallback uses x5 as scratch; safe to overwrite here as
137	    // the GPR loop already ran.
138	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
139	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
140	
141	    clear_cmderr_if_set();
142	    request_resume();
143	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
144	                   "ResumeDriver resume");
145	  }
146	
147	private:
148	  void request_halt()
149	  {
150	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
151	  }
152	
153	  void request_resume()
154	  {
155	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
156	  }
157	
158	  void write_64bit_register(uint16_t regno, uint64_t value)
159	  {
160	    write_register_abstract(bus_, regno, value);
161	  }
162	
163	  // Abstract-first CSR write with Program Buffer fallback.
164	  // Tries an abstract register write; if the DM signals cmderr, clears it,
165	  // stages the value in scratch_gpr via abstract GPR write, then executes a
166	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
167	  // to x5 (t0) which the GPR restore loop overwrites later.
168	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
169	                                 uint8_t scratch_gpr = 5)
170	  {
171	    write_64bit_register(regno_csr(csr), value);
172	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
173	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
174	    write_64bit_register(regno_gpr(scratch_gpr), value);
175	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
176	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
177	  }
178	
179	  // Write a CSR-addressable register and clear any cmderr the DM raised.
180	  // Used for CSRs whose abstract-access support may be implementation
181	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
182	  // remaining writes.
183	  void write_csr_tolerant(uint16_t csr, uint64_t value)
184	  {
185	    write_64bit_register(regno_csr(csr), value);
186	    clear_cmderr_if_set();
187	  }
188	
189	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
190	  // is rejected until the bits are W1C-cleared. We tolerate per-register
191	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
192	  // error before resuming so the hart isn't left in a stuck state.
193	  // B17: record the last observed non-zero cmderr and a clear count so a
194	  // partially-broken restore is observable via the public accessors
195	  // instead of silently swallowed.
196	  void clear_cmderr_if_set()
197	  {
198	    const auto status = bus_.read(kAbstractcs);
199	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
200	    if (code != 0u) {
201	      last_observed_cmderr_ = code;
202	      ++cmderr_clear_count_;
203	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
204	    }
205	  }
206	
207	  DmiBus& bus_;
208	  uint32_t last_observed_cmderr_ = 0;
209	  uint64_t cmderr_clear_count_   = 0;
210	
211	public:
212	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
213	  // at least one abstract write tripped a sticky cmderr the restore
214	  // tolerated by clearing. cmderr_clear_count() is the total number of
215	  // such clears across all calls into clear_cmderr_if_set() this run.
216	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
217	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
218	};
219	
220	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
221	// via an Abstract Command. Halts-and-reads contract: caller must have the
222	// hart in the halted state. Shared by StateDrain (drain at exit), and by
223	// MeasureStartSnapshot (snapshot at K-th retire). If abstractcs.cmderr
224	// goes sticky after the command, the helper clears it and reports 0
225	// rather than blocking the caller -- a missing CSR mirrors as zero
226	// instead of corrupting the adjacent field.
227	inline auto read_register_64(DmiBus& bus, uint16_t regno,
228	                             const char* poll_label = "read_register_64")
229	  -> uint64_t
230	{
231	  using RD = ResumeDriver;
232	  bus.write(RD::kCommand,
233	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
234	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
235	  const auto status = bus.read(RD::kAbstractcs);
236	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
237	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
238	    return 0u;
239	  }
240	  const uint64_t lo = bus.read(RD::kData0);
241	  const uint64_t hi = bus.read(RD::kData1);
242	  return lo | (hi << 32);
243	}
244	
245	}  // namespace hybrid
