1	// QEMU TCG plugin: drains architectural state and exits when the guest
2	// executes `csrwi 0x7C0, 0`. Shares hybrid/insn_match.h and
3	// hybrid/state_abi.h with the vsim side.
4	
5	#include "hybrid/handoff_site.h"
6	#include "hybrid/insn_match.h"
7	#include "hybrid/reg_names.h"
8	#include "hybrid/state_abi.h"
9	#include "hybrid/v_drain_policy.h"
10	
11	#include "bbv_emit.h"
12	
13	#include <qemu-plugin.h>
14	
15	#include <glib.h>
16	
17	#include <fcntl.h>
18	#include <inttypes.h>
19	#include <stddef.h>
20	#include <stdint.h>
21	#include <stdio.h>
22	#include <stdlib.h>
23	#include <string.h>
24	#include <unistd.h>
25	#include <limits.h>
26	
27	QEMU_PLUGIN_EXPORT int qemu_plugin_version = QEMU_PLUGIN_VERSION;
28	
29	typedef struct {
30	    struct qemu_plugin_register *gpr[32];
31	    struct qemu_plugin_register *fpr[32];
32	    struct qemu_plugin_register *pc;
33	
34	    // M-mode CSRs as exposed by QEMU's gdbstub csr feature.
35	    struct qemu_plugin_register *mstatus;
36	    struct qemu_plugin_register *mepc;
37	    struct qemu_plugin_register *mtvec;
38	    struct qemu_plugin_register *mcause;
39	    struct qemu_plugin_register *mtval;
40	    struct qemu_plugin_register *mscratch;
41	    struct qemu_plugin_register *medeleg;
42	    struct qemu_plugin_register *mideleg;
43	    struct qemu_plugin_register *mip;
44	    struct qemu_plugin_register *mie;
45	    struct qemu_plugin_register *mcycle;
46	    struct qemu_plugin_register *minstret;
47	    struct qemu_plugin_register *satp;
48	
49	    struct qemu_plugin_register *pmpcfg[HYBRID_PMP_CFG_NUM];
50	    struct qemu_plugin_register *pmpaddr[HYBRID_PMP_ADDR_NUM];
51	
52	    struct qemu_plugin_register *vstart;
53	    struct qemu_plugin_register *vxsat;
54	    struct qemu_plugin_register *vxrm;
55	    struct qemu_plugin_register *vcsr;
56	    struct qemu_plugin_register *vtype;
57	    struct qemu_plugin_register *vl;
58	    struct qemu_plugin_register *vlenb;
59	    struct qemu_plugin_register *vreg[32];
60	
61	    // icount-trigger mode: per-vcpu retired-insn counter, incremented in
62	    // on_icount_tick. When icount_target is reached, the same drain path
63	    // as CSR/PC mode fires (on_handoff -> write_state_atomic -> exit 200).
64	    uint64_t icount_retired;
65	} VcpuRegs;
66	
67	static struct qemu_plugin_scoreboard *vcpu_state;
68	static char *outfile_path;
69	
70	// PC-trigger mode: when enter_pc_arg is non-zero (set via plugin arg
71	// `enter_pc=0x...`), the CSR-insn matcher is bypassed entirely and the
72	// drain callback is registered only for instructions whose vaddr equals
73	// enter_pc_arg. The kind reported on the drain is HYBRID_HANDOFF_ENTER
74	// (entry into vsim), matching CSR-mode `csrwi 0x7C0, 0` semantics.
75	static uint64_t enter_pc_arg;
76	static int pc_mode;
77	
78	// icount-trigger mode: when icount_target is non-zero (set via plugin arg
79	// `icount=N`), every translated insn gets an exec callback that bumps a
80	// per-vcpu counter; on threshold-cross the drain fires at that insn
81	// boundary. Coexists with CSR/PC modes - either trigger can win.
82	static uint64_t icount_target;
83	static int icount_mode;
84	
85	// BBV-emit mode (SimPoint profile): when bbv_mode is set (plugin args
86	// `bbv_out=PATH,slice=N`), every translated insn gets an exec callback
87	// that ticks a global BBV counter; one .bb row per N retired insns is
88	// flushed to PATH. Coexists with the drain triggers - independently
89	// registered before icount so that on co-firing (icount target == slice
90	// multiple) the slice row is emitted before exit(200).
91	static BbvEmit *bbv_emit;
92	static char    *bbv_out_path;
93	static uint64_t bbv_slice_target;
94	static int      bbv_mode;
95	
96	// Slice-consume mode (SimPoint replay; F11): when slice_consume_mode is
97	// set (plugin args `slice=N,slice_at=K`), the plugin counts slice
98	// boundaries (one boundary per N retired insns) and drains at the end
99	// of slice index K (0-based). With K=2 and slice=1000, drain fires at
100	// insn 3000 - the boundary that closes the third slice. The orchestrator
101	// chains one invocation per SimPoint cluster-representative slice idx.
102	// Shares the `slice=` parameter with BBV-emit; works independently of
103	// whether `bbv_out=` is also set.
104	static uint64_t slice_at_target;
105	static int      slice_consume_mode;
106	static uint64_t slice_consume_acc;
107	static uint64_t slice_consume_idx;
108	
109	// Drain-at-exit mode (F14): when drain_at_exit_mode is set (plugin arg
110	// `drain_at_exit=1`), the plugin registers a per-insn exec callback that
111	// bumps `atexit_insn_count`, and a `qemu_plugin_register_atexit_cb` that
112	// drains state on natural program exit (e.g. semihosting EXIT). The
113	// atexit callback overrides s.minstret with the plugin counter so the
114	// caller (./hsim estimate --icount 0) gets a true retired-insn count
115	// independent of QEMU's PMU semantics (which can return host ticks on
116	// system-mode without `-icount`). `drained_already` suppresses the
117	// atexit path if any other trigger (CSR/PC/icount/slice) drained first.
118	static int      drain_at_exit_mode;
119	static volatile int drained_already;
120	static uint64_t atexit_insn_count;
121	
122	static struct qemu_plugin_register *find_reg(GArray *regs, const char *name)
123	{
124	    for (guint i = 0; i < regs->len; i++) {
125	        qemu_plugin_reg_descriptor *rd =
126	            &g_array_index(regs, qemu_plugin_reg_descriptor, i);
127	        if (g_ascii_strcasecmp(rd->name, name) == 0) {
128	            return rd->handle;
129	        }
130	    }
131	    return NULL;
132	}
