134	// Lazily resolves register handles. The plugin's vcpu_init runs before
135	// QEMU has registered the dynamic gdb coprocessors (FPU, virtual, csr,
136	// vector), so qemu_plugin_get_registers() returns only the 33 core CPU
137	// regs at that moment. By the time the entry trigger fires, all dynamic
138	// features are registered and a fresh call returns the full list.
139	static void resolve_handles(VcpuRegs *v)
140	{
141	    g_autoptr(GArray) regs = qemu_plugin_get_registers();
142	    for (int i = 0; i < 32; i++) {
143	        v->gpr[i] = find_reg(regs, hybrid_gpr_names[i]);
144	        v->fpr[i] = find_reg(regs, hybrid_fpr_names[i]);
145	    }
146	    v->pc = find_reg(regs, "pc");
147	
148	    v->mstatus  = find_reg(regs, "mstatus");
149	    v->mepc     = find_reg(regs, "mepc");
150	    v->mtvec    = find_reg(regs, "mtvec");
151	    v->mcause   = find_reg(regs, "mcause");
152	    v->mtval    = find_reg(regs, "mtval");
153	    v->mscratch = find_reg(regs, "mscratch");
154	    v->medeleg  = find_reg(regs, "medeleg");
155	    v->mideleg  = find_reg(regs, "mideleg");
156	    v->mip      = find_reg(regs, "mip");
157	    v->mie      = find_reg(regs, "mie");
158	    v->mcycle   = find_reg(regs, "mcycle");
159	    v->minstret = find_reg(regs, "minstret");
160	    v->satp     = find_reg(regs, "satp");
161	
162	    char buf[16];
163	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++) {
164	        g_snprintf(buf, sizeof(buf), "pmpcfg%d", i);
165	        v->pmpcfg[i] = find_reg(regs, buf);
166	    }
167	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++) {
168	        g_snprintf(buf, sizeof(buf), "pmpaddr%d", i);
169	        v->pmpaddr[i] = find_reg(regs, buf);
170	    }
171	
172	    v->vstart = find_reg(regs, "vstart");
173	    v->vxsat  = find_reg(regs, "vxsat");
174	    v->vxrm   = find_reg(regs, "vxrm");
175	    v->vcsr   = find_reg(regs, "vcsr");
176	    v->vtype  = find_reg(regs, "vtype");
177	    v->vl     = find_reg(regs, "vl");
178	    v->vlenb  = find_reg(regs, "vlenb");
179	    for (int i = 0; i < 32; i++) {
180	        g_snprintf(buf, sizeof(buf), "v%d", i);
181	        v->vreg[i] = find_reg(regs, buf);
182	    }
183	}
184	
185	static uint64_t read_reg64(struct qemu_plugin_register *h)
186	{
187	    if (!h) return 0;
188	    g_autoptr(GByteArray) buf = g_byte_array_new();
189	    int sz = qemu_plugin_read_register(h, buf);
190	    if (sz <= 0) return 0;
191	    uint64_t v = 0;
192	    memcpy(&v, buf->data, sz < 8 ? (size_t) sz : 8);
193	    return v;
194	}
195	
196	// Reads up to `dst_max` bytes from a register handle. Returns the byte
197	// count written (0 on failure or NULL handle). Used for vector regs whose
198	// width = vlenb bytes.
199	static size_t read_reg_bytes(struct qemu_plugin_register *h,
200	                             uint8_t *dst, size_t dst_max)
201	{
202	    if (!h || dst_max == 0) return 0;
203	    g_autoptr(GByteArray) buf = g_byte_array_new();
204	    int sz = qemu_plugin_read_register(h, buf);
205	    if (sz <= 0) return 0;
206	    size_t n = (size_t) sz < dst_max ? (size_t) sz : dst_max;
207	    memcpy(dst, buf->data, n);
208	    return n;
209	}
