248	// Drain CPU state to outfile_path. pc is computed by the caller (from a
249	// HandoffSite for trigger paths, or 0 for the atexit path which lacks an
250	// insn context). If minstret_override is non-zero, it replaces QEMU's PMU
251	// minstret in the state file (used by drain_at_exit mode to record a
252	// plugin-counted retired-insn total). Does NOT call exit -- caller
253	// decides exit(200) (normal trigger) vs _exit(200) (inside atexit chain).
254	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
255	                                uint64_t minstret_override)
256	{
257	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
258	    resolve_handles(v);
259	    struct hybrid_state_v1 s = {0};
260	    s.magic   = HYBRID_STATE_MAGIC;
261	    s.version = HYBRID_STATE_VERSION;
262	    s.flags   = HYBRID_FLAG_RV64;
263	    s.hart_id = vcpu_idx;
264	    s.priv    = 3;
265	    s.pc      = pc;
266	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
267	
268	    // Floating-point: only set FP flag if at least one handle was bound,
269	    // i.e. QEMU advertised the FPU feature (D extension).
270	    int has_fp = 0;
271	    for (int i = 0; i < 32; i++) {
272	        s.fpr[i] = read_reg64(v->fpr[i]);
273	        if (v->fpr[i]) has_fp = 1;
274	    }
275	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
276	
277	    s.mstatus  = read_reg64(v->mstatus);
278	    s.mepc     = read_reg64(v->mepc);
279	    s.mtvec    = read_reg64(v->mtvec);
280	    s.mcause   = read_reg64(v->mcause);
281	    s.mtval    = read_reg64(v->mtval);
282	    s.mscratch = read_reg64(v->mscratch);
283	    s.medeleg  = read_reg64(v->medeleg);
284	    s.mideleg  = read_reg64(v->mideleg);
285	    s.mip      = read_reg64(v->mip);
286	    s.mie      = read_reg64(v->mie);
287	    s.mcycle   = read_reg64(v->mcycle);
288	    s.minstret = minstret_override ? minstret_override
289	                                   : read_reg64(v->minstret);
290	    s.satp     = read_reg64(v->satp);
291	
292	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
293	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
294	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
295	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
296	
297	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
298	    // bounds the per-register byte count copied into vreg[]. The policy
299	    // helper (hybrid_v_drain_policy) decides SKIP/OK/ABORT from the
300	    // handle truthiness so we don't conflate "stub missing vlenb" with
301	    // "V disabled at runtime"; see include/hybrid/v_drain_policy.h.
302	    s.vstart = read_reg64(v->vstart);
303	    s.vxsat  = read_reg64(v->vxsat);
304	    s.vxrm   = read_reg64(v->vxrm);
305	    s.vcsr   = read_reg64(v->vcsr);
306	    s.vtype  = read_reg64(v->vtype);
307	    s.vl     = read_reg64(v->vl);
308	    s.vlenb  = read_reg64(v->vlenb);
309	    int has_other_v = (v->vstart || v->vxsat || v->vxrm || v->vcsr
310	                       || v->vtype || v->vl);
311	    if (!has_other_v) {
312	        for (int i = 0; i < 32; i++)
313	            if (v->vreg[i]) { has_other_v = 1; break; }
314	    }
315	    HybridVDrainPolicy vpol = hybrid_v_drain_policy(
316	        v->vlenb != NULL, has_other_v, s.vlenb);
317	    if (vpol == HYBRID_V_DRAIN_ABORT) {
318	        fprintf(stderr,
319	                "hybrid_handoff: stub advertised V CSRs/regs but not vlenb; "
320	                "refusing to drain partial V state\n");
321	        exit(2);
322	    }
323	    if (vpol == HYBRID_V_DRAIN_OK) {
324	        s.flags |= HYBRID_FLAG_V;
325	        size_t bytes = s.vlenb < HYBRID_VLEN_BYTES_MAX
326	                     ? (size_t) s.vlenb
327	                     : (size_t) HYBRID_VLEN_BYTES_MAX;
328	        for (int i = 0; i < 32; i++)
329	            (void) read_reg_bytes(v->vreg[i],
330	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
331	                                  bytes);
332	    }
333	
334	    if (write_state_atomic(&s, outfile_path) != 0) {
335	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
336	        exit(2);
337	    }
338	    fprintf(stderr,
339	            "hybrid_handoff: drained state to %s (pc=%#" PRIx64 "), exiting\n",
340	            outfile_path, s.pc);
341	}
342	
343	static void on_handoff(unsigned int vcpu_idx, void *udata)
344	{
345	    const HandoffSite *site = (const HandoffSite *) udata;
346	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
347	    // F14: suppress the atexit drain path now that we have a real trigger.
348	    drained_already = 1;
349	    // PC via translation-time vaddr+size; reading the gdbstub PC inside the
350	    // exec callback can lag the actual current insn when V instructions
351	    // retire just before the trigger (TCG defers PC writes for performance).
352	    drain_state_to_file(vcpu_idx, compute_handoff_pc(site), 0);
353	    // 200 == kExitHandoffToQemu in verilator/src/hybrid/exit_codes.hpp.
354	    // Distinguishes drain from workload completion (0) so the orchestrator
355	    // can decide the next spawn.
356	    exit(200);
357	}
358	
359	// F14: per-insn tick. Increments a global counter every retired insn so the
360	// drain-at-exit path can report a true retired-insn total (independent of
361	// QEMU's PMU semantics).
362	static void on_count_tick(unsigned int vcpu_idx, void *udata)
363	{
364	    (void) vcpu_idx;
365	    (void) udata;
366	    atexit_insn_count++;
367	}
368	
369	// F14: atexit drain. Fires when QEMU exits naturally (e.g. guest semihosting
370	// EXIT). The semihosting EXIT runs on the vCPU thread, so current_cpu is
371	// still set and qemu_plugin_read_register works. If any other trigger
372	// already drained, return immediately (drained_already guards against
373	// double drain). Inside an atexit handler, exit() is UB per C11 7.22.4.4;
374	// use _exit() to skip the rest of the atexit chain.
375	static void on_atexit(qemu_plugin_id_t id, void *udata)
376	{
377	    (void) id;
378	    (void) udata;
379	    if (drained_already) return;
380	    if (!drain_at_exit_mode) return;
381	    // pc=0 is a positive marker that the atexit path drained (no trigger).
382	    drain_state_to_file(0, 0, atexit_insn_count);
383	    fflush(stderr);
384	    _exit(200);
385	}
386	
387	// Per-insn tick for icount mode. udata is the per-insn HandoffSite
388	// pre-allocated at translation time, so on_handoff's compute_handoff_pc
389	// returns the lag-free post-trigger PC (same property as the CSR path).
390	static void on_icount_tick(unsigned int vcpu_idx, void *udata)
391	{
392	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
393	    if (++v->icount_retired < icount_target) return;
394	    on_handoff(vcpu_idx, udata);
395	}
396	
397	// Per-insn tick for BBV-emit mode. udata is the bb_id (1-based) cast to
398	// pointer; that mapping is stable across calls because bbv_emit_assign_id
399	// is hashed by TB-start PC. The tick attributes one insn to the bb_id and
400	// flushes a slice row when the per-slice counter saturates.
401	static void on_bbv_tick(unsigned int vcpu_idx, void *udata)
402	{
403	    (void) vcpu_idx;
404	    uint64_t bb_id = (uint64_t) GPOINTER_TO_UINT(udata);
405	    bbv_emit_tick(bbv_emit, bb_id);
406	}
407	
408	// Per-insn tick for slice-consume mode (F11). Counts insns into the
409	// slice accumulator; on each slice boundary increments slice_consume_idx
410	// and resets the accumulator. Once slice_consume_idx exceeds the target
411	// slice index, drains via on_handoff at that same insn boundary. udata
412	// is the per-insn HandoffSite (allocated at translation time) so the
413	// post-trigger PC reaches on_handoff lag-free.
414	static void on_slice_consume_tick(unsigned int vcpu_idx, void *udata)
415	{
416	    if (++slice_consume_acc < bbv_slice_target) return;
417	    slice_consume_acc = 0;
418	    if (slice_consume_idx++ < slice_at_target) return;
419	    // After the post-increment above, slice_consume_idx == slice_at_target+1
420	    // (the count of fully retired slices). Log so the e2e test can verify
421	    // drain timing without relying on minstret (which is a cycle-counter
422	    // proxy on andes-ax45mpv and does not track plugin-counted insns).
423	    fprintf(stderr,
424	            "hybrid_handoff: slice-consume drain (idx=%" PRIu64
425	            " target=%" PRIu64 ")\n",
426	            slice_consume_idx, slice_at_target);
427	    on_handoff(vcpu_idx, udata);
428	}
429	
430	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
431	{
432	    (void) id;
433	    size_t n = qemu_plugin_tb_n_insns(tb);
434	
435	    // BBV-mode: assign a stable bb_id to this TB (1-based, hashed by
436	    // TB-start vaddr). Same id is shared by every insn in the TB.
437	    uint64_t bb_id = 0;
438	    if (bbv_mode && n > 0) {
439	        uint64_t tb_pc = qemu_plugin_insn_vaddr(qemu_plugin_tb_get_insn(tb, 0));
440	        bb_id = bbv_emit_assign_id(bbv_emit, tb_pc);
441	    }
442	
443	    for (size_t i = 0; i < n; i++) {
444	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
445	
446	        // F14 count tick: registered FIRST so the count is incremented
447	        // before any trigger callback can call exit(200). NO_REGS keeps
448	        // the per-insn cost minimal (a single uint64 add).
449	        if (drain_at_exit_mode) {
450	            qemu_plugin_register_vcpu_insn_exec_cb(
451	                insn, on_count_tick, QEMU_PLUGIN_CB_NO_REGS, NULL);
452	        }
453	
454	        // BBV callback is registered BEFORE icount so that if both modes
455	        // fire on the same insn (icount target == slice multiple), the
456	        // slice row is emitted before exit(200) is called.
457	        if (bbv_mode) {
458	            qemu_plugin_register_vcpu_insn_exec_cb(
459	                insn, on_bbv_tick, QEMU_PLUGIN_CB_NO_REGS,
460	                GUINT_TO_POINTER((guint) bb_id));
461	        }
462	
463	        // Slice-consume callback (F11). Registered after BBV so a BBV
464	        // row at the same boundary is flushed first; ordering vs icount
465	        // is irrelevant (both drain).
466	        if (slice_consume_mode) {
467	            HandoffSite *site = g_new0(HandoffSite, 1);
468	            site->kind  = HYBRID_HANDOFF_ENTER;
469	            site->vaddr = qemu_plugin_insn_vaddr(insn);
470	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
471	            qemu_plugin_register_vcpu_insn_exec_cb(
472	                insn, on_slice_consume_tick, QEMU_PLUGIN_CB_R_REGS, site);
473	        }
474	
475	        if (icount_mode) {
476	            HandoffSite *site = g_new0(HandoffSite, 1);
477	            site->kind  = HYBRID_HANDOFF_ENTER;
478	            site->vaddr = qemu_plugin_insn_vaddr(insn);
479	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
480	            qemu_plugin_register_vcpu_insn_exec_cb(
481	                insn, on_icount_tick, QEMU_PLUGIN_CB_R_REGS, site);
482	        }
483	
484	        if (pc_mode) {
485	            // PC-trigger mode: vaddr-only match. qemu_plugin_insn_size lets
486	            // a future fixture park enter_pc on a compressed insn -- next-PC
487	            // is computed from the API-reported size, not assumed to be 4.
488	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
489	            HandoffSite *site = g_new0(HandoffSite, 1);
490	            site->kind  = HYBRID_HANDOFF_ENTER;
491	            site->vaddr = qemu_plugin_insn_vaddr(insn);
492	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
493	            qemu_plugin_register_vcpu_insn_exec_cb(
494	                insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
495	            continue;
496	        }
497	
498	        // CSR-trigger mode (default).
499	        // B18 (documented limit): CSR marker is `csrwi 0x7C0, {0,1}`, a
500	        // 32-bit (sz==4) insn. RV32C has no compressed csrrwi today, so
501	        // the sz!=4 skip is correct for the current ABI. If a future
502	        // RISC-V extension adds a 16-bit CSR write encoding the marker
503	        // would have to switch to a different opcode form and this gate
504	        // must be relaxed in lockstep.
505	        size_t sz = qemu_plugin_insn_size(insn);
506	        if (sz != 4) continue;
507	        uint32_t raw = 0;
508	        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
509	            continue;
510	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
511	        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
512	        HandoffSite *site = g_new0(HandoffSite, 1);
513	        site->kind  = kind;
514	        site->vaddr = qemu_plugin_insn_vaddr(insn);
515	        site->size  = (uint32_t) sz;
516	        qemu_plugin_register_vcpu_insn_exec_cb(
517	            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
518	    }
519	}
