521	QEMU_PLUGIN_EXPORT int qemu_plugin_install(qemu_plugin_id_t id,
522	                                           const qemu_info_t *info,
523	                                           int argc, char **argv)
524	{
525	    (void) info;
526	    for (int i = 0; i < argc; i++) {
527	        g_auto(GStrv) tok = g_strsplit(argv[i], "=", 2);
528	        if (g_strcmp0(tok[0], "outfile") == 0 && tok[1]) {
529	            outfile_path = g_strdup(tok[1]);
530	        } else if (g_strcmp0(tok[0], "enter_pc") == 0 && tok[1]) {
531	            char *endp = NULL;
532	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
533	            if (!endp || *endp != '\0') {
534	                fprintf(stderr, "hybrid_handoff: invalid enter_pc=%s\n",
535	                        tok[1]);
536	                return -1;
537	            }
538	            enter_pc_arg = (uint64_t) v;
539	            pc_mode = 1;
540	        } else if (g_strcmp0(tok[0], "icount") == 0 && tok[1]) {
541	            char *endp = NULL;
542	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
543	            if (!endp || *endp != '\0' || v == 0) {
544	                fprintf(stderr, "hybrid_handoff: invalid icount=%s\n",
545	                        tok[1]);
546	                return -1;
547	            }
548	            icount_target = (uint64_t) v;
549	            icount_mode = 1;
550	        } else if (g_strcmp0(tok[0], "bbv_out") == 0 && tok[1]) {
551	            bbv_out_path = g_strdup(tok[1]);
552	            bbv_mode = 1;
553	        } else if (g_strcmp0(tok[0], "slice") == 0 && tok[1]) {
554	            char *endp = NULL;
555	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
556	            if (!endp || *endp != '\0' || v == 0) {
557	                fprintf(stderr, "hybrid_handoff: invalid slice=%s\n",
558	                        tok[1]);
559	                return -1;
560	            }
561	            bbv_slice_target = (uint64_t) v;
562	        } else if (g_strcmp0(tok[0], "slice_at") == 0 && tok[1]) {
563	            char *endp = NULL;
564	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
565	            if (!endp || *endp != '\0') {
566	                fprintf(stderr, "hybrid_handoff: invalid slice_at=%s\n",
567	                        tok[1]);
568	                return -1;
569	            }
570	            slice_at_target = (uint64_t) v;
571	            slice_consume_mode = 1;
572	        } else if (g_strcmp0(tok[0], "drain_at_exit") == 0 && tok[1]) {
573	            // F14: any non-zero value enables. "1" is the canonical form
574	            // hsim emits; other ints (incl. negatives parsed as huge unsigned)
575	            // also enable -- the flag is a binary switch, not a count.
576	            char *endp = NULL;
577	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
578	            if (!endp || *endp != '\0') {
579	                fprintf(stderr, "hybrid_handoff: invalid drain_at_exit=%s\n",
580	                        tok[1]);
581	                return -1;
582	            }
583	            drain_at_exit_mode = (v != 0);
584	        } else {
585	            fprintf(stderr, "hybrid_handoff: unknown option: %s\n", argv[i]);
586	            return -1;
587	        }
588	    }
589	    if (!outfile_path) {
590	        fputs("hybrid_handoff: outfile=PATH is required\n", stderr);
591	        return -1;
592	    }
593	    if (pc_mode) {
594	        fprintf(stderr,
595	                "hybrid_handoff: PC-mode enter=0x%" PRIx64 "\n",
596	                enter_pc_arg);
597	    }
598	    if (icount_mode) {
599	        fprintf(stderr,
600	                "hybrid_handoff: icount-mode target=%" PRIu64 "\n",
601	                icount_target);
602	    }
603	    if (bbv_mode) {
604	        if (bbv_slice_target == 0) {
605	            fputs("hybrid_handoff: bbv_out= requires slice=N\n", stderr);
606	            return -1;
607	        }
608	        bbv_emit = bbv_emit_new(bbv_out_path, bbv_slice_target);
609	        if (!bbv_emit) {
610	            fprintf(stderr, "hybrid_handoff: failed to open bbv_out=%s\n",
611	                    bbv_out_path);
612	            return -1;
613	        }
614	        fprintf(stderr,
615	                "hybrid_handoff: bbv-mode out=%s slice=%" PRIu64 "\n",
616	                bbv_out_path, bbv_slice_target);
617	    }
618	    if (slice_consume_mode) {
619	        if (bbv_slice_target == 0) {
620	            fputs("hybrid_handoff: slice_at= requires slice=N\n", stderr);
621	            return -1;
622	        }
623	        fprintf(stderr,
624	                "hybrid_handoff: slice-consume mode slice=%" PRIu64
625	                " slice_at=%" PRIu64 "\n",
626	                bbv_slice_target, slice_at_target);
627	    }
628	    if (drain_at_exit_mode) {
629	        fputs("hybrid_handoff: drain-at-exit mode enabled\n", stderr);
630	        qemu_plugin_register_atexit_cb(id, on_atexit, NULL);
631	    }
632	
633	    vcpu_state = qemu_plugin_scoreboard_new(sizeof(VcpuRegs));
634	    qemu_plugin_register_vcpu_tb_trans_cb(id, vcpu_tb_trans);
635	    return 0;
636	}
